INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Pipes and Filters
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist das Pipes-and-Filters-Muster ausschließlich für Datenverarbeitungssysteme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Es kann auch in anderen Bereichen wie Signalverarbeitung genutzt werden"}, {"text": "Ja", "correct": false, "because": "Anwendung ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Filter im Pipes-and-Filters-Muster unabhängig voneinander entwickelt und getestet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Filter sind modular und eigenständig"}, {"text": "Nein", "correct": false, "because": "Unabhängigkeit ist ein Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Pipes im Pipes-and-Filters-Muster immer Daten synchron verarbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Asynchrone Verarbeitung ist möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Reihenfolge der Filter im Pipes-and-Filters-Muster immer festgelegt?', 2, '[{"text": "Ja", "correct": true, "because": "Die Datenflussreihenfolge ist definiert"}, {"text": "Nein", "correct": false, "because": "Reihenfolge ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Pipes-and-Filters-Muster die Systemleistung durch parallele Verarbeitung verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Filter können parallel arbeiten"}, {"text": "Nein", "correct": false, "because": "Parallele Verarbeitung ist ein Vorteil"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponente im Pipes-and-Filters-Muster überträgt Daten zwischen Filtern?', 2, '[{"text": "Pipes", "correct": true, "because": "Pipes leiten Daten weiter"}, {"text": "Filter", "correct": false, "because": "Filter verarbeiten Daten"}, {"text": "Buffer", "correct": false, "because": "Nur Hilfsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil des Pipes-and-Filters-Musters ist am bedeutendsten?', 3, '[{"text": "Modularität", "correct": true, "because": "Filter sind unabhängig und austauschbar"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Nicht primär"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil tritt beim Pipes-and-Filters-Muster am häufigsten auf?', 2, '[{"text": "Overhead durch Datenübertragung", "correct": true, "because": "Pipes können Leistung beeinträchtigen"}, {"text": "Mangelnde Flexibilität", "correct": false, "because": "Eher flexibel"}, {"text": "Schwierige Entwicklung", "correct": false, "because": "Eher einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Filter im Pipes-and-Filters-Muster primär?', 2, '[{"text": "Daten transformation", "correct": true, "because": "Filter verarbeiten eingehende Daten"}, {"text": "Daten speicherung", "correct": false, "because": "Nicht primäre Aufgabe"}, {"text": "Datenübertragung", "correct": false, "because": "Aufgabe der Pipes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sollte bei der Planung eines Pipes-and-Filters-Systems Priorität haben?', 2, '[{"text": "Datenflusssteuerung", "correct": true, "because": "Definiert die Verarbeitungsreihenfolge"}, {"text": "Maximale Komplexität", "correct": false, "because": "Kontraproduktiv"}, {"text": "Minimale Modularität", "correct": false, "because": "Modularität ist Ziel"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Pipes-and-Filters-Muster?', 4, '[{"text": "Pipes", "correct": true, "because": "Übertragen Daten"}, {"text": "Filter", "correct": true, "because": "Verarbeiten Daten"}, {"text": "Datenquellen", "correct": true, "because": "Liefern Eingabedaten"}, {"text": "Benutzeroberfläche", "correct": false, "because": "Nicht Teil des Musters"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Pipes-and-Filters-Muster?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Filter sind austauschbar"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Filter können erneut genutzt werden"}, {"text": "Parallele Verarbeitung", "correct": true, "because": "Filter können gleichzeitig arbeiten"}, {"text": "Geringere Latenz", "correct": false, "because": "Eher höher durch Pipes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben können Filter im Pipes-and-Filters-Muster übernehmen?', 4, '[{"text": "Datenfilterung", "correct": true, "because": "Entfernt unerwünschte Daten"}, {"text": "Datenkonvertierung", "correct": true, "because": "Ändert Datenformate"}, {"text": "Datenanreicherung", "correct": true, "because": "Fügt Informationen hinzu"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es beim Pipes-and-Filters-Muster?', 3, '[{"text": "Datenflusskoordination", "correct": true, "because": "Reihenfolge muss gesteuert werden"}, {"text": "Leistungsverlust durch Pipes", "correct": true, "because": "Übertragung kann verzögern"}, {"text": "Fehlerverfolgung", "correct": true, "because": "Verteilter Fluss erschwert Debugging"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungsbereiche sind für das Pipes-and-Filters-Muster typisch?', 3, '[{"text": "Datenpipelines", "correct": true, "because": "Verarbeitungsketten"}, {"text": "Signalverarbeitung", "correct": true, "because": "Fließende Transformation"}, {"text": "Batchverarbeitung", "correct": true, "because": "Schrittweise Datenbearbeitung"}, {"text": "Benutzerinteraktion", "correct": false, "because": "Nicht primär"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Pipes übertragen Daten zwischen Filtern. b) Filter müssen synchron arbeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pipes ja, Synchronität nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Pipes-and-Filters-Muster fördert Modularität. b) Es ist nur für kleine Systeme geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modularität ja, Größe flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Filter können parallel verarbeiten. b) Die Reihenfolge der Filter ist flexibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Parallel ja, Reihenfolge fest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Pipes-and-Filters eignet sich für Datenpipelines. b) Es reduziert immer die Leistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pipelines ja, Leistung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Filter sind wiederverwendbar im Pipes-and-Filters-Muster. b) Es ist ausschließlich für synchrone Systeme geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederverwendung ja, Asynchron möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

